    // Elite coordinate - specific spawns
    ARMADYLEAN_GUARD(
            "Armadylean Guard",
            97,
            "Elite",
            "Coordinate",
            "Ranged or magic gear (CAN'T melee — it flies!)",
            "Food",
            "Flies! Must use ranged/magic/halberd. Max hit 10.",
            false
    ),

    BANDOSIAN_GUARD(
            "Bandosian Guard",
            125,
            "Elite",
            "Coordinate",
            "Best melee gear",
            "Food",
            "Melee only. Max hit 13.",
            false
    ),

    // Elite coordinate clues - wilderness
